    55→            padding: 20px;
    56→            border: 1px solid rgba(255,255,255,0.1);
    57→        }
    58→
    59→        .upload-area {
    60→            border: 2px dashed rgba(0,217,255,0.5);
    61→            border-radius: 12px;
    62→            padding: 60px 20px;
    63→            text-align: center;
    64→            cursor: pointer;
