    71→            background: rgba(0,217,255,0.1);
    72→        }
    73→
    74→        .upload-area.hidden {
    75→            display: none;
    76→        }
    77→
    78→        .upload-icon {
    79→            font-size: 4rem;
    80→            margin-bottom: 20px;
    81→        }
    82→
    83→        .upload-area h3 {
    84→            color: #00d9ff;
    85→            margin-bottom: 10px;
    86→        }
    87→
    88→        .upload-area p {
    89→            color: #8892b0;
    90→        }
    91→
    92→        #fileInput {
    93→            display: none;
    94→        }
    95→
    96→        .canvas-container {
    97→            position: relative;
    98→            display: none;
    99→            overflow: auto;
   100→            max-height: 70vh;
   101→            border-radius: 12px;
   102→        }
   103→
   104→        .canvas-container.active {
   105→            display: block;
   106→        }
   107→
   108→        #mainCanvas {
   109→            display: block;
   110→            cursor: crosshair;
   111→            border-radius: 8px;
   112→        }
   113→
   114→        .control-panel {
   115→            background: rgba(255,255,255,0.05);
   116→            border-radius: 16px;
   117→            padding: 25px;
   118→            border: 1px solid rgba(255,255,255,0.1);
   119→            height: fit-content;
   120→        }
   121→
   122→        .step-indicator {
   123→            display: flex;
   124→            justify-content: space-between;
   125→            margin-bottom: 30px;
   126→            position: relative;
   127→        }
   128→
   129→        .step-indicator::before {
   130→            content: '';
   131→            position: absolute;
   132→            top: 20px;
   133→            left: 30px;
   134→            right: 30px;
   135→            height: 2px;
   136→            background: rgba(255,255,255,0.2);
   137→        }
   138→
   139→        .step {
   140→            display: flex;
   141→            flex-direction: column;
   142→            align-items: center;
   143→            position: relative;
   144→            z-index: 1;
   145→        }
   146→
   147→        .step-number {
   148→            width: 40px;
   149→            height: 40px;
   150→            border-radius: 50%;
   151→            background: rgba(255,255,255,0.1);
   152→            display: flex;
   153→            align-items: center;
   154→            justify-content: center;
   155→            font-weight: bold;
   156→            margin-bottom: 8px;
   157→            transition: all 0.3s;
   158→        }
   159→
   160→        .step.active .step-number {
   161→            background: linear-gradient(135deg, #00d9ff, #00ff88);
   162→            color: #1a1a2e;
   163→        }
   164→
   165→        .step.completed .step-number {
   166→            background: #00ff88;
   167→            color: #1a1a2e;
   168→        }
   169→
   170→        .step-label {
   171→            font-size: 0.8rem;
   172→            color: #8892b0;
   173→        }
   174→
   175→        .step.active .step-label {
   176→            color: #00d9ff;
   177→        }
   178→
   179→        .current-task {
   180→            background: rgba(0,217,255,0.1);
   181→            border: 1px solid rgba(0,217,255,0.3);
   182→            border-radius: 12px;
   183→            padding: 20px;
   184→            margin-bottom: 20px;
   185→        }
   186→
   187→        .current-task h3 {
   188→            color: #00d9ff;
   189→            margin-bottom: 10px;
   190→            font-size: 1.1rem;
   191→        }
   192→
   193→        .current-task p {
   194→            color: #ccd6f6;
   195→            line-height: 1.6;
   196→        }
   197→
   198→        .color-selector {
   199→            margin-bottom: 20px;
   200→        }
   201→
   202→        .color-selector h4 {
   203→            margin-bottom: 12px;
   204→            color: #ccd6f6;
   205→        }
   206→
   207→        .color-options {
   208→            display: flex;
   209→            gap: 10px;
   210→            flex-wrap: wrap;
   211→        }
   212→
   213→        .color-btn {
   214→            width: 40px;
   215→            height: 40px;
   216→            border-radius: 50%;
   217→            border: 3px solid transparent;
   218→            cursor: pointer;
   219→            transition: all 0.3s;
   220→        }
   221→
   222→        .color-btn:hover, .color-btn.selected {
   223→            transform: scale(1.15);
   224→            border-color: #fff;
   225→        }
   226→
   227→        .color-btn.green { background: #22c55e; }
   228→        .color-btn.red { background: #ef4444; }
   229→        .color-btn.pink { background: #ec4899; }
   230→        .color-btn.blue { background: #3b82f6; }
   231→        .color-btn.yellow { background: #eab308; }
   232→        .color-btn.purple { background: #a855f7; }
   233→        .color-btn.orange { background: #f97316; }
   234→        .color-btn.white { background: #ffffff; }
   235→
   236→        .points-list {
   237→            margin-bottom: 20px;
   238→        }
   239→
   240→        .points-list h4 {
   241→            margin-bottom: 12px;
   242→            color: #ccd6f6;
   243→        }
   244→
   245→        .point-item {
   246→            display: flex;
   247→            align-items: center;
   248→            justify-content: space-between;
   249→            background: rgba(255,255,255,0.05);
   250→            padding: 10px 15px;
   251→            border-radius: 8px;
   252→            margin-bottom: 8px;
   253→        }
   254→
   255→        .point-info {
   256→            display: flex;
   257→            align-items: center;
   258→            gap: 10px;
   259→        }
   260→
   261→        .point-badge {
   262→            width: 28px;
   263→            height: 28px;
   264→            border-radius: 50%;
   265→            display: flex;
   266→            align-items: center;
   267→            justify-content: center;
   268→            font-size: 0.8rem;
   269→            font-weight: bold;
   270→        }
   271→
   272→        .point-badge.start-hand { background: #22c55e; color: #fff; }
   273→        .point-badge.start-foot { background: #3b82f6; color: #fff; }
   274→        .point-badge.end { background: #ef4444; color: #fff; }
   275→        .point-badge.route { background: #f97316; color: #fff; }
   276→
   277→        .delete-btn {
   278→            background: rgba(239,68,68,0.2);
   279→            border: none;
   280→            color: #ef4444;
   281→            width: 28px;
   282→            height: 28px;
   283→            border-radius: 50%;
   284→            cursor: pointer;
   285→            font-size: 1.2rem;
   286→            transition: all 0.3s;
   287→        }
   288→
   289→        .delete-btn:hover {
   290→            background: rgba(239,68,68,0.4);
   291→        }
   292→
   293→        .btn {
   294→            width: 100%;
   295→            padding: 14px 20px;
   296→            border: none;
   297→            border-radius: 10px;
   298→            font-size: 1rem;
   299→            font-weight: 600;
   300→            cursor: pointer;
   301→            transition: all 0.3s;
   302→            margin-bottom: 10px;
   303→        }
   304→
   305→        .btn-primary {
   306→            background: linear-gradient(135deg, #00d9ff, #00ff88);
   307→            color: #1a1a2e;
   308→        }
   309→
   310→        .btn-primary:hover {
   311→            transform: translateY(-2px);
   312→            box-shadow: 0 10px 30px rgba(0,217,255,0.3);
   313→        }
   314→
   315→        .btn-secondary {
   316→            background: rgba(255,255,255,0.1);
   317→            color: #ccd6f6;
   318→            border: 1px solid rgba(255,255,255,0.2);
   319→        }
   320→
   321→        .btn-secondary:hover {
   322→            background: rgba(255,255,255,0.2);
   323→        }
   324→
   325→        .btn-download {
   326→            background: linear-gradient(135deg, #f97316, #ef4444);
   327→            color: #fff;
   328→        }
   329→
   330→        .btn:disabled {
   331→            opacity: 0.5;
   332→            cursor: not-allowed;
   333→            transform: none !important;
   334→        }
   335→
   336→        .route-preview {
   337→            margin-top: 20px;
   338→            padding: 20px;
   339→            background: rgba(0,255,136,0.1);
   340→            border: 1px solid rgba(0,255,136,0.3);
   341→            border-radius: 12px;
   342→            display: none;
   343→        }
   344→
   345→        .route-preview.active {
   346→            display: block;
   347→        }
   348→
   349→        .route-preview h4 {
   350→            color: #00ff88;
   351→            margin-bottom: 15px;
   352→        }
   353→
   354→        .route-step {
   355→            display: flex;
   356→            gap: 12px;
   357→            margin-bottom: 12px;
   358→            padding: 12px;
   359→            background: rgba(255,255,255,0.05);
   360→            border-radius: 8px;
   361→        }
   362→
   363→        .route-step-number {
   364→            width: 30px;
   365→            height: 30px;
   366→            background: linear-gradient(135deg, #00d9ff, #00ff88);
   367→            border-radius: 50%;
   368→            display: flex;
   369→            align-items: center;
   370→            justify-content: center;
   371→            font-weight: bold;
   372→            color: #1a1a2e;
   373→            flex-shrink: 0;
   374→        }
   375→
   376→        .route-step-content h5 {
   377→            color: #ccd6f6;
   378→            margin-bottom: 4px;
   379→        }
   380→
   381→        .route-step-content p {
   382→            color: #8892b0;
   383→            font-size: 0.9rem;
   384→            line-height: 1.5;
   385→        }
   386→
   387→        .tip-box {
   388→            background: rgba(234,179,8,0.1);
   389→            border: 1px solid rgba(234,179,8,0.3);
   390→            border-radius: 8px;
   391→            padding: 12px;
   392→            margin-top: 15px;
   393→        }
   394→
   395→        .tip-box h5 {
   396→            color: #eab308;
   397→            margin-bottom: 8px;
   398→            font-size: 0.9rem;
   399→        }
   400→
   401→        .tip-box p {
   402→            color: #ccd6f6;
   403→            font-size: 0.85rem;
   404→            line-height: 1.5;
   405→        }
   406→
   407→        .loading-overlay {
   408→            position: fixed;
   409→            top: 0;
   410→            left: 0;
   411→            right: 0;
   412→            bottom: 0;
   413→            background: rgba(26,26,46,0.9);
   414→            display: none;
   415→            align-items: center;
   416→            justify-content: center;
   417→            z-index: 1000;
   418→        }
   419→
   420→        .loading-overlay.active {
   421→            display: flex;
   422→        }
   423→
   424→        .loading-content {
   425→            text-align: center;
   426→        }
   427→
   428→        .spinner {
   429→            width: 60px;
   430→            height: 60px;
   431→            border: 3px solid rgba(0,217,255,0.3);
   432→            border-top-color: #00d9ff;
   433→            border-radius: 50%;
   434→            animation: spin 1s linear infinite;
   435→            margin: 0 auto 20px;
   436→        }
   437→
   438→        @keyframes spin {
   439→            to { transform: rotate(360deg); }
   440→        }
   441→
   442→        .instructions-modal {
   443→            position: fixed;
   444→            top: 0;
   445→            left: 0;
   446→            right: 0;
   447→            bottom: 0;
   448→            background: rgba(26,26,46,0.95);
   449→            display: flex;
   450→            align-items: center;
   451→            justify-content: center;
   452→            z-index: 1000;
   453→        }
   454→
   455→        .instructions-modal.hidden {
   456→            display: none;
   457→        }
   458→
   459→        .modal-content {
   460→            background: rgba(255,255,255,0.05);
   461→            border: 1px solid rgba(255,255,255,0.1);
   462→            border-radius: 20px;
   463→            padding: 40px;
   464→            max-width: 600px;
   465→            width: 90%;
   466→        }
   467→
   468→        .modal-content h2 {
   469→            color: #00d9ff;
   470→            margin-bottom: 25px;
   471→            text-align: center;
   472→        }
   473→
   474→        .instruction-step {
   475→            display: flex;
   476→            gap: 15px;
   477→            margin-bottom: 20px;
   478→        }
   479→
   480→        .instruction-number {
   481→            width: 36px;
   482→            height: 36px;
   483→            background: linear-gradient(135deg, #00d9ff, #00ff88);
   484→            border-radius: 50%;
   485→            display: flex;
   486→            align-items: center;
   487→            justify-content: center;
   488→            font-weight: bold;
   489→            color: #1a1a2e;
   490→            flex-shrink: 0;
   491→        }
   492→
   493→        .instruction-text h4 {
   494→            color: #ccd6f6;
   495→            margin-bottom: 5px;
   496→        }
   497→
   498→        .instruction-text p {
   499→            color: #8892b0;
   500→            font-size: 0.95rem;
   501→        }
   502→
   503→        @media (max-width: 1024px) {
   504→            .main-content {
   505→                grid-template-columns: 1fr;
   506→            }
   507→        }
   508→    </style>
   509→</head>
   510→<body>
   511→    <!-- 使用说明弹窗 -->
   512→    <div class="instructions-modal" id="instructionsModal">
   513→        <div class="modal-content">
   514→            <h2>🧗 攀岩路线标注工具</h2>
   515→            <div class="instruction-step">
   516→                <div class="instruction-number">1</div>
   517→                <div class="instruction-text">
   518→                    <h4>上传岩点图片</h4>
   519→                    <p>点击上传区域或拖拽图片到指定位置</p>
   520→                </div>
   521→            </div>
   522→            <div class="instruction-step">
   523→                <div class="instruction-number">2</div>
   524→                <div class="instruction-text">
   525→                    <h4>选择路线颜色</h4>
   526→                    <p>选择你要标注的路线颜色（绿色、红色、粉色等）</p>
   527→                </div>
   528→            </div>
   529→            <div class="instruction-step">
   530→                <div class="instruction-number">3</div>
   531→                <div class="instruction-text">
   532→                    <h4>标记起点</h4>
   533→                    <p>在图片上点击标记起始手点（左手、右手）和脚点</p>
   534→                </div>
   535→            </div>
   536→            <div class="instruction-step">
   537→                <div class="instruction-number">4</div>
   538→                <div class="instruction-text">
   539→                    <h4>标记终点</h4>
   540→                    <p>点击标记路线的终点（顶点）</p>
   541→                </div>
   542→            </div>
   543→            <div class="instruction-step">
   544→                <div class="instruction-number">5</div>
   545→                <div class="instruction-text">
   546→                    <h4>添加中间点位</h4>
   547→                    <p>按攀爬顺序依次点击中间的抓点，系统会自动生成攀爬建议</p>
   548→                </div>
   549→            </div>
   550→            <button class="btn btn-primary" onclick="closeInstructions()" style="margin-top: 20px;">
   551→                开始使用 →
   552→            </button>
   553→        </div>
   554→    </div>
   555→
   556→    <!-- 加载动画 -->
   557→    <div class="loading-overlay" id="loadingOverlay">
   558→        <div class="loading-content">
   559→            <div class="spinner"></div>
   560→            <p>正在生成路线图...</p>
   561→        </div>
   562→    </div>
   563→
   564→    <div class="container">
   565→        <header>
   566→            <h1>🧗 攀岩路线标注</h1>
   567→            <p>上传岩点图片，标注你的攀爬路线</p>
   568→        </header>
   569→
   570→        <div class="main-content">
   571→            <!-- 图片区域 -->
   572→            <div class="image-section">
   573→                <div class="upload-area" id="uploadArea">
   574→                    <div class="upload-icon">📷</div>
   575→                    <h3>上传岩点图片</h3>
   576→                    <p>点击选择或拖拽图片到这里</p>
   577→                    <p style="margin-top: 10px; font-size: 0.9rem;">支持 JPG、PNG 格式</p>
   578→                </div>
   579→                <input type="file" id="fileInput" accept="image/*">
   580→
   581→                <div class="canvas-container" id="canvasContainer">
   582→                    <canvas id="mainCanvas"></canvas>
   583→                </div>
   584→            </div>
   585→
   586→            <!-- 控制面板 -->
   587→            <div class="control-panel">
   588→                <!-- 步骤指示器 -->
   589→                <div class="step-indicator">
   590→                    <div class="step active" id="step1">
   591→                        <div class="step-number">1</div>
   592→                        <span class="step-label">起点</span>
   593→                    </div>
   594→                    <div class="step" id="step2">
   595→                        <div class="step-number">2</div>
   596→                        <span class="step-label">终点</span>
   597→                    </div>
   598→                    <div class="step" id="step3">
   599→                        <div class="step-number">3</div>
   600→                        <span class="step-label">路线</span>
   601→                    </div>
   602→                    <div class="step" id="step4">
   603→                        <div class="step-number">4</div>
   604→                        <span class="step-label">完成</span>
   605→                    </div>
   606→                </div>
   607→
   608→                <!-- 当前任务提示 -->
   609→                <div class="current-task" id="currentTask">
   610→                    <h3>📍 第一步：标记起点</h3>
   611→                    <p>请在图片上依次点击：<br>
   612→                    • 左手起始点<br>
   613→                    • 右手起始点（可选）<br>
   614→                    • 左脚起始点<br>
   615→                    • 右脚起始点（可选）</p>
   616→                </div>
   617→
   618→                <!-- 颜色选择 -->
   619→                <div class="color-selector">
   620→                    <h4>🎨 选择路线颜色</h4>
   621→                    <div class="color-options">
   622→                        <button class="color-btn green selected" data-color="green" title="绿色"></button>
   623→                        <button class="color-btn red" data-color="red" title="红色"></button>
   624→                        <button class="color-btn pink" data-color="pink" title="粉色"></button>
   625→                        <button class="color-btn blue" data-color="blue" title="蓝色"></button>
   626→                        <button class="color-btn yellow" data-color="yellow" title="黄色"></button>
   627→                        <button class="color-btn purple" data-color="purple" title="紫色"></button>
   628→                        <button class="color-btn orange" data-color="orange" title="橙色"></button>
   629→                        <button class="color-btn white" data-color="white" title="白色"></button>
   630→                    </div>
   631→                </div>
   632→
   633→                <!-- 标记类型选择 -->
   634→                <div class="point-type-selector" id="pointTypeSelector">
   635→                    <h4>✋ 当前标记类型</h4>
   636→                    <div style="display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px;">
   637→                        <button class="btn btn-secondary point-type-btn active" data-type="left-hand" style="flex: 1; min-width: 45%;">
   638→                            🤚 左手
   639→                        </button>
   640→                        <button class="btn btn-secondary point-type-btn" data-type="right-hand" style="flex: 1; min-width: 45%;">
