  1042→        function redrawCanvas() {
  1043→            if (!state.image) return;
  1044→
  1045→            ctx.clearRect(0, 0, canvas.width, canvas.height);
  1046→            ctx.drawImage(state.image, 0, 0, canvas.width, canvas.height);
  1047→
  1048→            const mainColor = colorMap[state.selectedColor];
  1049→
  1050→            // 画路线连接线
  1051→            if (state.routePoints.length > 0 || state.endPoint) {
  1052→                ctx.beginPath();
  1053→                ctx.strokeStyle = mainColor;
  1054→                ctx.lineWidth = 3;
  1055→                ctx.setLineDash([8, 4]);
  1056→
  1057→                // 从起点开始
  1058→                if (state.startPoints.length > 0) {
  1059→                    const handStart = state.startPoints.find(p => p.type.includes('hand'));
  1060→                    if (handStart) {
  1061→                        ctx.moveTo(handStart.x, handStart.y);
  1062→
  1063→                        // 连接路线点
  1064→                        state.routePoints.forEach(point => {
  1065→                            ctx.lineTo(point.x, point.y);
  1066→                        });
  1067→
  1068→                        // 连接终点
  1069→                        if (state.endPoint) {
  1070→                            ctx.lineTo(state.endPoint.x, state.endPoint.y);
  1071→                        }
  1072→                    }
  1073→                }
  1074→
  1075→                ctx.stroke();
  1076→                ctx.setLineDash([]);
  1077→            }
  1078→
  1079→            // 画起点
  1080→            state.startPoints.forEach(point => {
  1081→                const isHand = point.type.includes('hand');
  1082→                drawPoint(point.x, point.y, isHand ? '#22c55e' : '#3b82f6', isHand ? '起' : '脚', 20);
  1083→            });
  1084→
  1085→            // 画终点
  1086→            if (state.endPoint) {
  1087→                drawPoint(state.endPoint.x, state.endPoint.y, '#ef4444', '终', 22);
  1088→            }
  1089→
  1090→            // 画路线点
  1091→            state.routePoints.forEach((point, index) => {
  1092→                const color = point.type === 'hand' ? mainColor : '#64748b';
  1093→                drawPoint(point.x, point.y, color, String(index + 1), 18);
  1094→            });
  1095→        }
