  1099→            ctx.beginPath();
  1100→            ctx.arc(x, y, radius + 4, 0, Math.PI * 2);
  1101→            ctx.strokeStyle = '#fff';
  1102→            ctx.lineWidth = 3;
  1103→            ctx.stroke();
  1104→
  1105→            // 内圈
  1106→            ctx.beginPath();
  1107→            ctx.arc(x, y, radius, 0, Math.PI * 2);
  1108→            ctx.fillStyle = color;
  1109→            ctx.fill();
  1110→            ctx.strokeStyle = '#fff';
  1111→            ctx.lineWidth = 2;
  1112→            ctx.stroke();
  1113→
  1114→            // 文字
  1115→            ctx.fillStyle = '#fff';
  1116→            ctx.font = `bold ${radius * 0.8}px sans-serif`;
  1117→            ctx.textAlign = 'center';
  1118→            ctx.textBaseline = 'middle';
  1119→            ctx.fillText(label, x, y);
  1120→        }
