  1143→        function generateFinalImage() {
  1144→            ctx.clearRect(0, 0, canvas.width, canvas.height);
  1145→            ctx.drawImage(state.image, 0, 0, canvas.width, canvas.height);
  1146→
  1147→            const mainColor = colorMap[state.selectedColor];
  1148→
  1149→            // 画箭头路线
  1150→            if (state.routePoints.length > 0 || state.endPoint) {
  1151→                const points = [];
  1152→
  1153→                const handStart = state.startPoints.find(p => p.type.includes('hand'));
  1154→                if (handStart) points.push(handStart);
  1155→                points.push(...state.routePoints);
  1156→                if (state.endPoint) points.push(state.endPoint);
  1157→
  1158→                // 画带箭头的路线
  1159→                for (let i = 0; i < points.length - 1; i++) {
  1160→                    drawArrow(points[i].x, points[i].y, points[i + 1].x, points[i + 1].y, mainColor);
  1161→                }
  1162→            }
  1163→
  1164→            // 画起点（带标签）
  1165→            state.startPoints.forEach(point => {
  1166→                const isHand = point.type.includes('hand');
  1167→                const side = point.type.includes('left') ? '左' : '右';
  1168→                const label = isHand ? `${side}手起` : `${side}脚`;
  1169→                drawLabeledPoint(point.x, point.y, isHand ? '#22c55e' : '#3b82f6', label, 24);
  1170→            });
  1171→
  1172→            // 画终点
  1173→            if (state.endPoint) {
  1174→                drawLabeledPoint(state.endPoint.x, state.endPoint.y, '#ef4444', '终点', 26);
  1175→            }
  1176→
  1177→            // 画路线点（带详细标签）
  1178→            state.routePoints.forEach((point, index) => {
  1179→                const sideLabel = point.side === 'left' ? '左' : '右';
  1180→                const typeLabel = point.type === 'hand' ? '手' : '脚';
  1181→                const label = `${index + 1}. ${sideLabel}${typeLabel}`;
  1182→                const color = point.type === 'hand' ? mainColor : '#64748b';
  1183→                drawLabeledPoint(point.x, point.y, color, label, 20);
  1184→            });
  1185→        }
