  1187→        function drawArrow(fromX, fromY, toX, toY, color) {
  1188→            const headLen = 15;
  1189→            const dx = toX - fromX;
  1190→            const dy = toY - fromY;
  1191→            const angle = Math.atan2(dy, dx);
  1192→
  1193→            // 缩短线条，不要画到点中心
  1194→            const dist = Math.sqrt(dx * dx + dy * dy);
  1195→            const shortenBy = 25;
  1196→            const ratio = (dist - shortenBy) / dist;
  1197→            const endX = fromX + dx * ratio;
