   915→        function loadImage(file) {
   916→            const reader = new FileReader();
   917→            reader.onload = (e) => {
   918→                const img = new Image();
   919→                img.onload = () => {
   920→                    state.image = img;
   921→                    state.imageLoaded = true;
   922→                    state.originalWidth = img.width;
   923→                    state.originalHeight = img.height;
   924→
   925→                    uploadArea.classList.add('hidden');
   926→                    canvas.classList.remove('hidden');
   927→
   928→                    fitToWindow();
   929→                };
   930→                img.src = e.target.result;
   931→            };
   932→            reader.readAsDataURL(file);
   933→        }
   934→
   935→        function setZoom(newZoom) {
   936→            state.zoom = Math.max(0.25, Math.min(4, newZoom));
   937→            document.getElementById('zoomLevel').textContent = Math.round(state.zoom * 100) + '%';
   938→
   939→            canvas.width = state.originalWidth * state.zoom;
   940→            canvas.height = state.originalHeight * state.zoom;
   941→
   942→            redrawCanvas();
