   945→        function fitToWindow() {
   946→            if (!state.image) return;
   947→
   948→            const wrapperRect = canvasWrapper.getBoundingClientRect();
   949→            const maxWidth = wrapperRect.width - 80;
   950→            const maxHeight = wrapperRect.height - 80;
   951→
   952→            const scaleX = maxWidth / state.originalWidth;
   953→            const scaleY = maxHeight / state.originalHeight;
   954→            const scale = Math.min(scaleX, scaleY, 1);
   955→
   956→            setZoom(scale);
   957→        }
