   959→        function handleCanvasClick(e) {
   960→            if (!state.imageLoaded) return;
   961→
   962→            const rect = canvas.getBoundingClientRect();
   963→            // 转换为原始图片坐标
   964→            const x = (e.clientX - rect.left) / state.zoom;
   965→            const y = (e.clientY - rect.top) / state.zoom;
   966→
   967→            switch (state.currentStep) {
   968→                case 1: addStartPoint(x, y); break;
   969→                case 2: setEndPoint(x, y); break;
   970→                case 3: addRoutePoint(x, y); break;
   971→            }
