  1260→        function drawArrowOnCtx(ctx, fromX, fromY, toX, toY, color) {
  1261→            const headLen = 15;
  1262→            const dx = toX - fromX;
  1263→            const dy = toY - fromY;
  1264→            const angle = Math.atan2(dy, dx);
  1265→            const dist = Math.sqrt(dx * dx + dy * dy);
  1266→            const shortenBy = 25;
  1267→            const ratio = (dist - shortenBy) / dist;
  1268→            const endX = fromX + dx * ratio;
  1269→            const endY = fromY + dy * ratio;
  1270→            const startX = fromX + dx * (shortenBy / dist);
  1271→            const startY = fromY + dy * (shortenBy / dist);
  1272→
  1273→            ctx.beginPath();
  1274→            ctx.moveTo(startX, startY);
  1275→            ctx.lineTo(endX, endY);
  1276→            ctx.strokeStyle = color;
  1277→            ctx.lineWidth = 4;
  1278→            ctx.stroke();
  1279→
  1280→            ctx.beginPath();
  1281→            ctx.moveTo(endX, endY);
  1282→            ctx.lineTo(endX - headLen * Math.cos(angle - Math.PI / 6), endY - headLen * Math.sin(angle - Math.PI / 6));
  1283→            ctx.moveTo(endX, endY);
  1284→            ctx.lineTo(endX - headLen * Math.cos(angle + Math.PI / 6), endY - headLen * Math.sin(angle + Math.PI / 6));
  1285→            ctx.strokeStyle = color;
  1286→            ctx.lineWidth = 4;
  1287→            ctx.stroke();
  1288→        }
  1289→
  1290→        function drawLabeledPointOnCtx(ctx, x, y, color, label, radius) {
  1291→            ctx.beginPath();
  1292→            ctx.arc(x, y, radius, 0, Math.PI * 2);
  1293→            ctx.fillStyle = color;
  1294→            ctx.fill();
  1295→            ctx.strokeStyle = '#fff';
  1296→            ctx.lineWidth = 3;
  1297→            ctx.stroke();
  1298→
  1299→            ctx.font = 'bold 14px sans-serif';
  1300→            const textWidth = ctx.measureText(label).width;
  1301→            const labelX = x + radius + 8;
  1302→            const labelY = y;
  1303→
  1304→            ctx.fillStyle = 'rgba(0, 0, 0, 0.8)';
  1305→            const padding = 6;
  1306→            ctx.beginPath();
  1307→            ctx.roundRect(labelX - padding, labelY - 12, textWidth + padding * 2, 24, 4);
  1308→            ctx.fill();
  1309→
  1310→            ctx.fillStyle = '#fff';
  1311→            ctx.textAlign = 'left';
  1312→            ctx.textBaseline = 'middle';
  1313→            ctx.fillText(label, labelX, labelY);
  1314→        }
