function generateClimbingInstructions() {
    let stepsHtml = '';
    let stepNum = 1;

    const leftHand = state.startPoints.find(p => p.type === 'left-hand');
    const rightHand = state.startPoints.find(p => p.type === 'right-hand');
    const leftFoot = state.startPoints.find(p => p.type === 'left-foot');
    const rightFoot = state.startPoints.find(p => p.type === 'right-foot');

    let startDesc = '起步：';
    if (leftHand) startDesc += '左手抓握、';
    if (rightHand) startDesc += '右手抓握、';
    if (leftFoot) startDesc += '左脚踩稳、';
    if (rightFoot) startDesc += '右脚踩稳';
    startDesc = startDesc.replace(/、$/, '');

    stepsHtml += `
        <div class="route-step">
            <div class="route-step-number">${stepNum++}</div>
            <div class="route-step-content">
                <h5>起步准备</h5>
                <p>${startDesc}。确保重心稳定。</p>
            </div>
        </div>
    `;

    state.routePoints.forEach((point, index) => {
        const sideLabel = point.side === 'left' ? '左' : '右';
        const typeLabel = point.type === 'hand' ? '手' : '脚';
        const action = point.type === 'hand' ? '抓握' : '踩稳';

        let tip = '';
        const prevPoint = index > 0 ? state.routePoints[index - 1] : (leftHand || rightHand);
        if (prevPoint) {
            const dy = point.y - prevPoint.y;
            const dx = point.x - prevPoint.x;
            if (dy < -50) tip = '向上发力，重心跟随';
            else if (Math.abs(dx) > 80) tip = dx > 0 ? '向右侧移，贴墙' : '向左侧移，贴墙';
            else tip = '稳定移动，三点固定';
        }

        stepsHtml += `
            <div class="route-step">
                <div class="route-step-number">${stepNum++}</div>
                <div class="route-step-content">
                    <h5>${sideLabel}${typeLabel}${action}第${index + 1}点</h5>
                    <p>${tip}</p>
                </div>
            </div>
        `;
    });

    if (state.endPoint) {
        stepsHtml += `
            <div class="route-step">
                <div class="route-step-number">${stepNum}</div>
                <div class="route-step-content">
                    <h5>完成攀登</h5>
                    <p>双手抓握终点，完成！🎉</p>
                </div>
            </div>
        `;
    }

    document.getElementById('routeSteps').innerHTML = stepsHtml;

    // 技巧提示
    const tips = [];
    if (state.routePoints.length > 5) tips.push('路线较长，注意分配体力');
    const handPoints = state.routePoints.filter(p => p.type === 'hand');
    const footPoints = state.routePoints.filter(p => p.type === 'foot');
    if (handPoints.length > footPoints.length * 2) tips.push('多用脚点分担手臂力量');
    tips.push(`专注${colorNames[state.selectedColor]}路线岩点`);
    tips.push('保持呼吸均匀');
    document.getElementById('climbingTips').innerHTML = tips.map(t => `• ${t}`).join('<br>');
}

function downloadImage() {
    const link = document.createElement('a');
    link.download = `climbing-route-${state.selectedColor}-${Date.now()}.png`;
    link.href = state.exportData;
    link.click();
}

function resetAll() {
    state.currentStep = 1;
    state.startPoints = [];
    state.endPoint = null;
    state.routePoints = [];

    updateStepIndicator();
    updateCurrentTask();
    updatePointsList();

    document.getElementById('confirmStartBtn').style.display = 'none';
    document.getElementById('confirmEndBtn').style.display = 'none';
    document.getElementById('generateBtn').style.display = 'none';
    document.getElementById('downloadBtn').style.display = 'none';
    document.getElementById('pointTypeSelector').style.display = 'block';
    document.getElementById('routePreview').classList.remove('active');

