function generateClimbingInstructions() {
    let stepsHtml = '';
    let stepNum = 1;

    const leftHand = state.startPoints.find(p => p.type === 'left-hand');
    const rightHand = state.startPoints.find(p => p.type === 'right-hand');
    const leftFoot = state.startPoints.find(p => p.type === 'left-foot');
    const rightFoot = state.startPoints.find(p => p.type === 'right-foot');

    // 计算总步数
    const totalSteps = 1 + state.routePoints.length + (state.endPoint ? 1 : 0);

    // 第一步：起步准备
    let startActions = [];
    if (leftHand) startActions.push('左手抓握起点岩点');
    if (rightHand) startActions.push('右手抓握起点岩点');
    if (leftFoot) startActions.push('左脚踩稳脚点');
    if (rightFoot) startActions.push('右脚踩稳脚点');

    stepsHtml += `
        <div class="route-step">
            <div class="route-step-number">${stepNum}</div>
            <div class="route-step-content">
                <h5>第${stepNum}步：起步准备 (共${totalSteps}步)</h5>
                <p>${startActions.join('，')}。身体贴近岩壁，重心放低，准备开始攀爬。</p>
            </div>
        </div>
    `;
    stepNum++;

    // 中间路线点
    state.routePoints.forEach((point, index) => {
        const sideLabel = point.side === 'left' ? '左' : '右';
        const typeLabel = point.type === 'hand' ? '手' : '脚';
        const action = point.type === 'hand' ? '抓握' : '踩踏';
        const bodyPart = point.type === 'hand' ? '手臂' : '腿部';

        // 根据位置变化生成详细建议
        let tip = '';
        let technique = '';
        const prevPoint = index > 0 ? state.routePoints[index - 1] : (leftHand || rightHand || leftFoot || rightFoot);

        if (prevPoint) {
            const dy = point.y - prevPoint.y;
            const dx = point.x - prevPoint.x;
            const distance = Math.sqrt(dx * dx + dy * dy);

            // 方向判断
            if (dy < -80) {
                tip = '大幅向上移动';
                technique = '用腿部发力推动身体向上，手臂主要用于保持平衡和抓握，避免纯靠手臂拉起。';
            } else if (dy < -30) {
                tip = '向上攀爬';
                technique = '重心跟随移动，保持三点固定原则，确保稳定后再移动下一个肢体。';
            } else if (dy > 50) {
                tip = '向下移动';
                technique = '控制下降速度，保持身体贴墙，用脚点支撑重心。';
            } else if (dx > 80) {
                tip = '大幅向右横移';
                technique = '身体侧向右方，右脚先找到支撑点，然后转移重心，最后移动左侧肢体。';
            } else if (dx < -80) {
                tip = '大幅向左横移';
                technique = '身体侧向左方，左脚先找到支撑点，然后转移重心，最后移动右侧肢体。';
            } else if (Math.abs(dx) > 30) {
                tip = dx > 0 ? '略向右移动' : '略向左移动';
                technique = '保持身体平衡，稳定移动。';
            } else {
                tip = '小幅调整位置';
                technique = '稳定移动，保持三点固定。';
            }

            // 距离判断
            if (distance > 150) {
                technique += ' ⚠️ 跨度较大，可能需要动态移动（dyno）。';
            }
        }

        // 手脚特定建议
        if (point.type === 'hand') {
            technique += ` 抓握时注意${sideLabel}手握点方式，根据岩点形状选择抓握、捏握或侧拉。`;
        } else {
            technique += ` 脚踩稳后再转移重心，用脚尖内侧精准踩点。`;
        }

        stepsHtml += `
            <div class="route-step">
                <div class="route-step-number">${stepNum}</div>
                <div class="route-step-content">
                    <h5>第${stepNum}步：${sideLabel}${typeLabel}${action}第${index + 1}号点</h5>
                    <p><strong>${tip}</strong> — ${technique}</p>
                </div>
            </div>
        `;
        stepNum++;
    });

    // 最后一步：完成
    if (state.endPoint) {
        // 计算终点相对于最后一个点的位置
        let finishTip = '';
        const lastPoint = state.routePoints.length > 0
            ? state.routePoints[state.routePoints.length - 1]
            : (leftHand || rightHand);

        if (lastPoint) {
            const dy = state.endPoint.y - lastPoint.y;
            if (dy < -50) {
                finishTip = '最后一个大动作！用力向上，双手依次抓握终点岩点。';
            } else {
                finishTip = '稳定移动到终点位置，双手牢牢抓握终点岩点。';
            }
        }

        stepsHtml += `
            <div class="route-step">
                <div class="route-step-number">${stepNum}</div>
                <div class="route-step-content">
                    <h5>第${stepNum}步：完成攀登！🎉</h5>
                    <p>${finishTip} 保持抓握3秒，确认完成后可以安全下降。恭喜完成${colorNames[state.selectedColor]}路线！</p>
                </div>
            </div>
        `;
    }

    // 显示总览
    const summaryHtml = `
        <div style="background: rgba(0,217,255,0.15); border-radius: 8px; padding: 12px; margin-bottom: 15px; border: 1px solid rgba(0,217,255,0.3);">
            <div style="font-size: 0.9rem; color: #00d9ff; font-weight: 600; margin-bottom: 8px;">
                📊 路线总览
            </div>
            <div style="font-size: 0.8rem; color: #ccd6f6; line-height: 1.6;">
                • 路线颜色：<strong>${colorNames[state.selectedColor]}</strong><br>
                • 总步数：<strong>${totalSteps} 步</strong><br>
                • 手点动作：<strong>${state.routePoints.filter(p => p.type === 'hand').length} 次</strong><br>
                • 脚点动作：<strong>${state.routePoints.filter(p => p.type === 'foot').length} 次</strong>
            </div>
        </div>
    `;

    document.getElementById('routeSteps').innerHTML = summaryHtml + stepsHtml;

    // 技巧提示
    const tips = [];
    tips.push('攀爬前先观察整条路线，在脑中预演动作');
    if (state.routePoints.length > 5) {
        tips.push('路线较长，注意在稳定点位休息和调整呼吸');
    }
    const handPoints = state.routePoints.filter(p => p.type === 'hand');
    const footPoints = state.routePoints.filter(p => p.type === 'foot');
    if (handPoints.length > footPoints.length * 2) {
        tips.push('手点较多，记得多利用脚点分担手臂力量');
    }
    tips.push('保持呼吸均匀，发力时呼气');
    tips.push('如果感觉力竭，可以在稳定点甩手休息');

    document.getElementById('climbingTips').innerHTML = tips.map(t => `• ${t}`).join('<br>');
}

