                technique = '保持身体平衡，稳定移动。';
            } else {
                tip = '小幅调整位置';
                technique = '稳定移动，保持三点固定。';
            }

            // 距离判断
            if (distance > 150) {
                technique += ' ⚠️ 跨度较大，可能需要动态移动（dyno）。';
            }
        }

        // 手脚特定建议
        if (point.type === 'hand') {
            technique += ` 抓握时注意${sideLabel}手握点方式，根据岩点形状选择抓握、捏握或侧拉。`;
        } else {
            technique += ` 脚踩稳后再转移重心，用脚尖内侧精准踩点。`;
        }

        stepsHtml += `
            <div class="route-step">
                <div class="route-step-number">${stepNum}</div>
                <div class="route-step-content">
                    <h5>第${stepNum}步：${sideLabel}${typeLabel}${action}第${index + 1}号点</h5>
                    <p><strong>${tip}</strong> — ${technique}</p>
                </div>
            </div>
        `;
        stepNum++;
    });

    // 最后一步：完成
    if (state.endPoint) {
        // 计算终点相对于最后一个点的位置
        let finishTip = '';
        const lastPoint = state.routePoints.length > 0
            ? state.routePoints[state.routePoints.length - 1]
            : (leftHand || rightHand);

        if (lastPoint) {
            const dy = state.endPoint.y - lastPoint.y;
            if (dy < -50) {
                finishTip = '最后一个大动作！用力向上，双手依次抓握终点岩点。';
            } else {
                finishTip = '稳定移动到终点位置，双手牢牢抓握终点岩点。';
            }
        }

        stepsHtml += `
            <div class="route-step">
                <div class="route-step-number">${stepNum}</div>
                <div class="route-step-content">
                    <h5>第${stepNum}步：完成攀登！🎉</h5>
                    <p>${finishTip} 保持抓握3秒，确认完成后可以安全下降。恭喜完成${colorNames[state.selectedColor]}路线！</p>
                </div>
            </div>
        `;
    }

    // 显示总览
    const summaryHtml = `
        <div style="background: rgba(0,217,255,0.15); border-radius: 8px; padding: 12px; margin-bottom: 15px; border: 1px solid rgba(0,217,255,0.3);">
            <div style="font-size: 0.9rem; color: #00d9ff; font-weight: 600; margin-bottom: 8px;">
                📊 路线总览
            </div>
            <div style="font-size: 0.8rem; color: #ccd6f6; line-height: 1.6;">
                • 路线颜色：<strong>${colorNames[state.selectedColor]}</strong><br>
                • 总步数：<strong>${totalSteps} 步</strong><br>
                • 手点动作：<strong>${state.routePoints.filter(p => p.type === 'hand').length} 次</strong><br>
                • 脚点动作：<strong>${state.routePoints.filter(p => p.type === 'foot').length} 次</strong>
            </div>
        </div>
    `;

    document.getElementById('routeSteps').innerHTML = summaryHtml + stepsHtml;

    // 技巧提示
    const tips = [];
    tips.push('攀爬前先观察整条路线，在脑中预演动作');
    if (state.routePoints.length > 5) {
        tips.push('路线较长，注意在稳定点位休息和调整呼吸');
    }
    const handPoints = state.routePoints.filter(p => p.type === 'hand');
    const footPoints = state.routePoints.filter(p => p.type === 'foot');
    if (handPoints.length > footPoints.length * 2) {
        tips.push('手点较多，记得多利用脚点分担手臂力量');
    }
    tips.push('保持呼吸均匀，发力时呼气');
    tips.push('如果感觉力竭，可以在稳定点甩手休息');

    document.getElementById('climbingTips').innerHTML = tips.map(t => `• ${t}`).join('<br>');
}

