    margin-top: 15px;
    padding: 15px;
    background: rgba(0,255,136,0.1);
    border: 1px solid rgba(0,255,136,0.3);
    border-radius: 10px;
    display: none;
    max-height: 300px;
    overflow-y: auto;
}

.route-preview.active {
    display: block;
}

.route-preview h4 {
    color: #00ff88;
    margin-bottom: 12px;
    font-size: 0.9rem;
}

.route-step {
    display: flex;
    gap: 10px;
    margin-bottom: 10px;
    padding: 10px;
    background: rgba(255,255,255,0.05);
    border-radius: 6px;
}

.route-step-number {
    width: 24px;
    height: 24px;
    background: linear-gradient(135deg, #00d9ff, #00ff88);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.75rem;
    color: #1a1a2e;
    flex-shrink: 0;
}

.route-step-content h5 {
    color: #ccd6f6;
    margin-bottom: 3px;
    font-size: 0.8rem;
}

.route-step-content p {
    color: #8892b0;
    font-size: 0.75rem;
    line-height: 1.4;
}

.tip-box {
    background: rgba(234,179,8,0.1);
    border: 1px solid rgba(234,179,8,0.3);
    border-radius: 6px;
    padding: 10px;
    margin-top: 12px;
}

.tip-box h5 {
    color: #eab308;
    margin-bottom: 6px;
    font-size: 0.8rem;
}

.tip-box p {
    color: #ccd6f6;
    font-size: 0.75rem;
    line-height: 1.5;
}

