/* 路线说明弹窗 - 大面板 */
.route-modal {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(26,26,46,0.95);
    display: none;
    align-items: center;
    justify-content: center;
    z-index: 1000;
    padding: 40px;
}

.route-modal.active {
    display: flex;
}

.route-modal-content {
    background: linear-gradient(135deg, rgba(30,30,50,0.98), rgba(20,20,40,0.98));
    border: 1px solid rgba(0,255,136,0.3);
    border-radius: 20px;
    width: 100%;
    max-width: 900px;
    max-height: 90vh;
    display: flex;
    flex-direction: column;
    box-shadow: 0 20px 60px rgba(0,0,0,0.5);
}

.route-modal-header {
    padding: 25px 30px;
    border-bottom: 1px solid rgba(255,255,255,0.1);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.route-modal-header h2 {
    color: #00ff88;
    font-size: 1.5rem;
    display: flex;
    align-items: center;
    gap: 10px;
}

.route-modal-close {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    border: none;
    background: rgba(255,255,255,0.1);
    color: #fff;
    font-size: 1.5rem;
    cursor: pointer;
    transition: all 0.2s;
}

.route-modal-close:hover {
    background: rgba(239,68,68,0.3);
    color: #ef4444;
}

.route-modal-body {
    flex: 1;
    overflow-y: auto;
    padding: 30px;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 30px;
}

.route-steps-section {
    display: flex;
    flex-direction: column;
}

.route-steps-section h3 {
    color: #00d9ff;
    font-size: 1.1rem;
    margin-bottom: 20px;
    padding-bottom: 10px;
    border-bottom: 1px solid rgba(0,217,255,0.3);
}

.route-steps-list {
    flex: 1;
    overflow-y: auto;
}

.route-step {
    display: flex;
    gap: 15px;
    margin-bottom: 15px;
    padding: 15px;
    background: rgba(255,255,255,0.05);
    border-radius: 12px;
    border-left: 4px solid #00d9ff;
}

.route-step-number {
    width: 36px;
    height: 36px;
    background: linear-gradient(135deg, #00d9ff, #00ff88);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 1rem;
    color: #1a1a2e;
    flex-shrink: 0;
}

.route-step-content {
    flex: 1;
}

.route-step-content h5 {
    color: #fff;
    margin-bottom: 8px;
    font-size: 1rem;
}

.route-step-content p {
    color: #a0aec0;
    font-size: 0.95rem;
    line-height: 1.6;
}

.route-tips-section h3 {
    color: #eab308;
    font-size: 1.1rem;
    margin-bottom: 20px;
    padding-bottom: 10px;
    border-bottom: 1px solid rgba(234,179,8,0.3);
}

.tip-box {
    background: rgba(234,179,8,0.1);
    border: 1px solid rgba(234,179,8,0.3);
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 20px;
}

.tip-box p {
    color: #ccd6f6;
    font-size: 0.95rem;
    line-height: 1.8;
}

.route-summary {
    background: rgba(0,217,255,0.1);
    border: 1px solid rgba(0,217,255,0.3);
    border-radius: 12px;
    padding: 20px;
}

.route-summary h4 {
    color: #00d9ff;
    margin-bottom: 15px;
    font-size: 1rem;
}

.summary-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 15px;
}

.summary-item {
    text-align: center;
    padding: 15px;
    background: rgba(255,255,255,0.05);
    border-radius: 8px;
}

.summary-item .value {
    font-size: 1.8rem;
    font-weight: bold;
    color: #00ff88;
}

.summary-item .label {
    font-size: 0.85rem;
    color: #8892b0;
    margin-top: 5px;
}

.route-modal-footer {
    padding: 20px 30px;
    border-top: 1px solid rgba(255,255,255,0.1);
    display: flex;
    gap: 15px;
    justify-content: center;
}

.route-modal-footer .btn {
    width: auto;
    padding: 12px 30px;
}

/* 小提示按钮 */
.view-guide-btn {
    background: rgba(0,255,136,0.2);
    border: 1px solid rgba(0,255,136,0.4);
    color: #00ff88;
}

.view-guide-btn:hover {
    background: rgba(0,255,136,0.3);
}

@media (max-width: 800px) {
    .route-modal-body {
        grid-template-columns: 1fr;
    }
}

