    fileInput.addEventListener('change', (e) => {
        if (e.target.files[0]) loadImage(e.target.files[0]);
    });

    // 颜色选择
    document.querySelectorAll('.color-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            document.querySelectorAll('.color-btn').forEach(b => b.classList.remove('selected'));
            btn.classList.add('selected');
            state.selectedColor = btn.dataset.color;
            redrawCanvas();
        });
    });

    // 点位类型
    document.querySelectorAll('.point-type-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            document.querySelectorAll('.point-type-btn').forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            state.currentPointType = btn.dataset.type;
        });
    });

    // Canvas 点击
    canvas.addEventListener('click', handleCanvasClick);

    // 缩放控制
    document.getElementById('zoomIn').addEventListener('click', () => setZoom(state.zoom + 0.25));
    document.getElementById('zoomOut').addEventListener('click', () => setZoom(state.zoom - 0.25));
    document.getElementById('fitBtn').addEventListener('click', fitToWindow);
    document.getElementById('actualBtn').addEventListener('click', () => setZoom(1));

    // 鼠标滚轮缩放
    canvasWrapper.addEventListener('wheel', (e) => {
        if (e.ctrlKey || e.metaKey) {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.1 : 0.1;
            setZoom(state.zoom + delta);
        }
    });

    // 按钮
    document.getElementById('confirmStartBtn').addEventListener('click', confirmStart);
    document.getElementById('confirmEndBtn').addEventListener('click', confirmEnd);
    document.getElementById('generateBtn').addEventListener('click', generateRoute);
    document.getElementById('downloadBtn').addEventListener('click', downloadImage);
    document.getElementById('resetBtn').addEventListener('click', resetAll);
}

function loadImage(file) {
    const reader = new FileReader();
    reader.onload = (e) => {
        const img = new Image();
        img.onload = () => {
            state.image = img;
            state.imageLoaded = true;
            state.originalWidth = img.width;
            state.originalHeight = img.height;

            uploadArea.classList.add('hidden');
            canvas.classList.remove('hidden');

            fitToWindow();
        };
        img.src = e.target.result;
    };
    reader.readAsDataURL(file);
}

function setZoom(newZoom) {
    state.zoom = Math.max(0.25, Math.min(4, newZoom));
    document.getElementById('zoomLevel').textContent = Math.round(state.zoom * 100) + '%';

    canvas.width = state.originalWidth * state.zoom;
    canvas.height = state.originalHeight * state.zoom;

    redrawCanvas();

