            tips.push('如果感觉力竭，可以在稳定点甩手休息');

            document.getElementById('climbingTips').innerHTML = tips.map(t => `• ${t}`).join('<br>');
        }

        function downloadImage() {
            const link = document.createElement('a');
            link.download = `climbing-route-${state.selectedColor}-${Date.now()}.png`;
            link.href = state.exportData;
            link.click();
        }

        function resetAll() {
            state.currentStep = 1;
            state.startPoints = [];
            state.endPoint = null;
            state.routePoints = [];

            updateStepIndicator();
            updateCurrentTask();
            updatePointsList();

            document.getElementById('confirmStartBtn').style.display = 'none';
            document.getElementById('confirmEndBtn').style.display = 'none';
            document.getElementById('generateBtn').style.display = 'none';
            document.getElementById('downloadBtn').style.display = 'none';
            document.getElementById('pointTypeSelector').style.display = 'block';
            document.getElementById('routePreview').classList.remove('active');

            if (state.imageLoaded) redrawCanvas();
        }

        init();
    </script>
</body>
