   806→    <script>
   807→        // 状态
   808→        const state = {
   809→            selectedColor: 'green',
   810→            currentAction: 'left-hand',
   811→            steps: [], // {action, x, y, description}
   812→            image: null,
   813→            imageLoaded: false,
   814→            zoom: 1,
   815→            originalWidth: 0,
