   822→            yellow: '#eab308', purple: '#a855f7', orange: '#f97316', white: '#ffffff'
   823→        };
   824→
   825→        const colorNames = {
   826→            green: '绿色', red: '红色', pink: '粉色', blue: '蓝色',
   827→            yellow: '黄色', purple: '紫色', orange: '橙色', white: '白色'
   828→        };
   829→
   830→        const actionLabels = {
   831→            'left-hand': '左手抓握',
   832→            'right-hand': '右手抓握',
   833→            'left-foot': '左脚踩踏',
