   850→        const ctx = canvas.getContext('2d');
   851→
   852→        function init() {
   853→            // 上传
   854→            uploadArea.addEventListener('click', () => fileInput.click());
   855→            uploadArea.addEventListener('dragover', e => { e.preventDefault(); uploadArea.style.borderColor = '#00d9ff'; });
   856→            uploadArea.addEventListener('dragleave', () => { uploadArea.style.borderColor = 'rgba(0,217,255,0.5)'; });
   857→            uploadArea.addEventListener('drop', e => {
   858→                e.preventDefault();
