   885→            // 缩放
   886→            document.getElementById('zoomIn').addEventListener('click', () => setZoom(state.zoom + 0.25));
   887→            document.getElementById('zoomOut').addEventListener('click', () => setZoom(state.zoom - 0.25));
   888→            document.getElementById('fitBtn').addEventListener('click', fitToWindow);
   889→            document.getElementById('actualBtn').addEventListener('click', () => setZoom(1));
   890→            canvasWrapper.addEventListener('wheel', e => {
   891→                if (e.ctrlKey || e.metaKey) {
   892→                    e.preventDefault();
   893→                    setZoom(state.zoom + (e.deltaY > 0 ? -0.1 : 0.1));
   894→                }
   895→            });
   896→
   897→            // 按钮
   898→            document.getElementById('generateBtn').addEventListener('click', generateRoute);
   899→            document.getElementById('downloadBtn').addEventListener('click', downloadImage);
   900→            document.getElementById('downloadBtnModal').addEventListener('click', downloadImage);
   901→            document.getElementById('viewGuideBtn').addEventListener('click', () => document.getElementById('routeModal').classList.add('active'));
   902→            document.getElementById('undoBtn').addEventListener('click', undoStep);
   903→            document.getElementById('resetBtn').addEventListener('click', resetAll);
   904→            document.getElementById('closeRouteModal').addEventListener('click', () => document.getElementById('routeModal').classList.remove('active'));
   905→            document.getElementById('closeRouteModalBtn').addEventListener('click', () => document.getElementById('routeModal').classList.remove('active'));
