   907→
   908→        function loadImage(file) {
   909→            const reader = new FileReader();
   910→            reader.onload = e => {
   911→                const img = new Image();
   912→                img.onload = () => {
   913→                    state.image = img;
   914→                    state.imageLoaded = true;
   915→                    state.originalWidth = img.width;
   916→                    state.originalHeight = img.height;
   917→                    uploadArea.classList.add('hidden');
   918→                    canvas.classList.remove('hidden');
   919→                    fitToWindow();
   920→                };
   921→                img.src = e.target.result;
   922→            };
   923→            reader.readAsDataURL(file);
   924→        }
   925→
   926→        function setZoom(newZoom) {
   927→            state.zoom = Math.max(0.25, Math.min(4, newZoom));
   928→            document.getElementById('zoomLevel').textContent = Math.round(state.zoom * 100) + '%';
   929→            canvas.width = state.originalWidth * state.zoom;
   930→            canvas.height = state.originalHeight * state.zoom;
   931→            redrawCanvas();
   932→        }
   933→
   934→        function fitToWindow() {
   935→            if (!state.image) return;
   936→            const rect = canvasWrapper.getBoundingClientRect();
   937→            const scale = Math.min((rect.width - 80) / state.originalWidth, (rect.height - 80) / state.originalHeight, 1);
   938→            setZoom(scale);
   939→        }
   940→
   941→        function handleCanvasClick(e) {
   942→            if (!state.imageLoaded) return;
   943→            const rect = canvas.getBoundingClientRect();
   944→            const x = (e.clientX - rect.left) / state.zoom;
   945→            const y = (e.clientY - rect.top) / state.zoom;
   946→
   947→            // 添加步骤
   948→            state.steps.push({
   949→                action: state.currentAction,
   950→                x, y,
   951→                description: generateStepDescription(state.currentAction, state.steps.length)
   952→            });
   953→
   954→            updateStepsList();
   955→            redrawCanvas();
   956→            updateButtons();
   957→        }
   958→
   959→        function generateStepDescription(action, stepIndex) {
   960→            const prevStep = stepIndex > 0 ? state.steps[stepIndex - 1] : null;
   961→
   962→            if (action === 'start') return '准备起步，调整好身体姿势';
