  1036→        function redrawCanvas() {
  1037→            if (!state.image) return;
  1038→            ctx.clearRect(0, 0, canvas.width, canvas.height);
  1039→            ctx.drawImage(state.image, 0, 0, canvas.width, canvas.height);
  1040→
  1041→            const z = state.zoom;
  1042→            const mainColor = colorMap[state.selectedColor];
  1043→
  1044→            // 画连接线
  1045→            if (state.steps.length > 1) {
  1046→                ctx.beginPath();
  1047→                ctx.strokeStyle = mainColor;
  1048→                ctx.lineWidth = 3 * z;
  1049→                ctx.setLineDash([8 * z, 4 * z]);
  1050→                ctx.moveTo(state.steps[0].x * z, state.steps[0].y * z);
  1051→                for (let i = 1; i < state.steps.length; i++) {
  1052→                    ctx.lineTo(state.steps[i].x * z, state.steps[i].y * z);
  1053→                }
  1054→                ctx.stroke();
  1055→                ctx.setLineDash([]);
  1056→            }
  1057→
  1058→            // 画每个点
  1059→            state.steps.forEach((step, index) => {
  1060→                let color = mainColor;
  1061→                let label = String(index + 1);
  1062→
  1063→                if (step.action === 'start') { color = '#22c55e'; label = '起'; }
  1064→                else if (step.action === 'finish') { color = '#ef4444'; label = '终'; }
  1065→                else if (step.action.includes('foot')) { color = '#64748b'; }
  1066→
  1067→                drawPoint(step.x * z, step.y * z, color, label, 18 * z);
  1068→            });
  1069→        }
  1070→
  1071→        function drawPoint(x, y, color, label, radius) {
  1072→            ctx.beginPath();
  1073→            ctx.arc(x, y, radius + 3, 0, Math.PI * 2);
  1074→            ctx.strokeStyle = '#fff';
  1075→            ctx.lineWidth = 3;
  1076→            ctx.stroke();
  1077→
  1078→            ctx.beginPath();
  1079→            ctx.arc(x, y, radius, 0, Math.PI * 2);
  1080→            ctx.fillStyle = color;
  1081→            ctx.fill();
  1082→
  1083→            ctx.fillStyle = '#fff';
  1084→            ctx.font = `bold ${radius * 0.8}px sans-serif`;
  1085→            ctx.textAlign = 'center';
  1086→            ctx.textBaseline = 'middle';
  1087→            ctx.fillText(label, x, y);
  1088→        }
