  1105→        function generateFinalImage() {
  1106→            const exportCanvas = document.createElement('canvas');
  1107→            exportCanvas.width = state.originalWidth;
  1108→            exportCanvas.height = state.originalHeight;
  1109→            const exportCtx = exportCanvas.getContext('2d');
  1110→            exportCtx.drawImage(state.image, 0, 0);
  1111→
  1112→            const mainColor = colorMap[state.selectedColor];
  1113→
  1114→            // 画箭头
  1115→            for (let i = 0; i < state.steps.length - 1; i++) {
  1116→                drawArrow(exportCtx, state.steps[i].x, state.steps[i].y, state.steps[i+1].x, state.steps[i+1].y, mainColor);
  1117→            }
  1118→
  1119→            // 画点和标签
  1120→            state.steps.forEach((step, index) => {
  1121→                let color = mainColor;
  1122→                let label = `${index + 1}. ${actionLabels[step.action].slice(0,2)}`;
  1123→
  1124→                if (step.action === 'start') { color = '#22c55e'; label = '起步'; }
  1125→                else if (step.action === 'finish') { color = '#ef4444'; label = '终点'; }
  1126→                else if (step.action.includes('foot')) { color = '#64748b'; }
  1127→
  1128→                drawLabeledPoint(exportCtx, step.x, step.y, color, label, 22);
