  1134→        function drawArrow(ctx, x1, y1, x2, y2, color) {
  1135→            const dx = x2 - x1, dy = y2 - y1;
  1136→            const angle = Math.atan2(dy, dx);
  1137→            const dist = Math.sqrt(dx*dx + dy*dy);
  1138→            const shorten = 28;
  1139→            const ratio = (dist - shorten) / dist;
  1140→            const startX = x1 + dx * (shorten/dist), startY = y1 + dy * (shorten/dist);
  1141→            const endX = x1 + dx * ratio, endY = y1 + dy * ratio;
  1142→
  1143→            ctx.beginPath();
  1144→            ctx.moveTo(startX, startY);
  1145→            ctx.lineTo(endX, endY);
  1146→            ctx.strokeStyle = color;
  1147→            ctx.lineWidth = 4;
  1148→            ctx.stroke();
  1149→
  1150→            ctx.beginPath();
  1151→            ctx.moveTo(endX, endY);
  1152→            ctx.lineTo(endX - 12*Math.cos(angle-Math.PI/6), endY - 12*Math.sin(angle-Math.PI/6));
  1153→            ctx.moveTo(endX, endY);
  1154→            ctx.lineTo(endX - 12*Math.cos(angle+Math.PI/6), endY - 12*Math.sin(angle+Math.PI/6));
  1155→            ctx.stroke();
  1156→        }
  1157→
  1158→        function drawLabeledPoint(ctx, x, y, color, label, radius) {
  1159→            ctx.beginPath();
  1160→            ctx.arc(x, y, radius, 0, Math.PI * 2);
  1161→            ctx.fillStyle = color;
  1162→            ctx.fill();
  1163→            ctx.strokeStyle = '#fff';
  1164→            ctx.lineWidth = 3;
  1165→            ctx.stroke();
  1166→
  1167→            ctx.font = 'bold 13px sans-serif';
  1168→            const textWidth = ctx.measureText(label).width;
  1169→            const labelX = x + radius + 6;
  1170→
  1171→            ctx.fillStyle = 'rgba(0,0,0,0.85)';
  1172→            ctx.beginPath();
  1173→            ctx.roundRect(labelX - 4, y - 10, textWidth + 8, 20, 4);
  1174→            ctx.fill();
  1175→
  1176→            ctx.fillStyle = '#fff';
  1177→            ctx.textAlign = 'left';
  1178→            ctx.textBaseline = 'middle';
  1179→            ctx.fillText(label, labelX, y);
  1180→        }
