  1182→        function generateGuide() {
  1183→            let html = '';
  1184→
  1185→            state.steps.forEach((step, index) => {
  1186→                const isStart = step.action === 'start';
  1187→                const isEnd = step.action === 'finish';
  1188→                const stepClass = isStart ? 'start-step' : (isEnd ? 'end-step' : '');
  1189→
  1190→                // 生成详细攀爬建议
  1191→                let advice = '';
  1192→                const prevStep = index > 0 ? state.steps[index - 1] : null;
  1193→
  1194→                if (isStart) {
  1195→                    advice = '面向岩壁，调整好站位。确认起步手点和脚点位置，身体贴近岩壁，重心放低。深呼吸，准备开始攀爬。';
  1196→                } else if (isEnd) {
