  1198→                } else {
  1199→                    const actionType = step.action.includes('hand') ? '手' : '脚';
  1200→                    const side = step.action.includes('left') ? '左' : '右';
  1201→
  1202→                    advice = `${side}${actionType}`;
  1203→
  1204→                    if (prevStep) {
  1205→                        const dx = step.x - prevStep.x;
  1206→                        const dy = step.y - prevStep.y;
  1207→                        const distance = Math.sqrt(dx*dx + dy*dy);
  1208→
  1209→                        if (dy < -80) {
  1210→                            advice += '向上移动。用腿部发力推动身体向上，手臂保持平衡，避免纯靠手臂拉起。';
  1211→                        } else if (dy < -30) {
  1212→                            advice += '向上攀爬。保持三点固定，稳定后再移动。';
  1213→                        } else if (dy > 50) {
  1214→                            advice += '向下调整。控制好重心，脚点支撑。';
  1215→                        } else if (Math.abs(dx) > 80) {
  1216→                            advice += dx > 0 ? '大幅右移。身体侧向右方，重心跟随。' : '大幅左移。身体侧向左方，重心跟随。';
  1217→                        } else {
  1218→                            advice += '稳定移动。保持身体平衡，三点固定。';
  1219→                        }
  1220→
  1221→                        if (distance > 150) {
  1222→                            advice += ' ⚠️ 跨度较大，可能需要动态发力。';
  1223→                        }
  1224→
  1225→                        if (actionType === '手') {
  1226→                            advice += ' 根据岩点形状选择抓握方式。';
  1227→                        } else {
  1228→                            advice += ' 用脚尖内侧精准踩点，踩稳后再转移重心。';
  1229→                        }
  1230→                    }
  1231→                }
  1232→
  1233→                html += `
