  1235→                        <div class="guide-step-num">${index + 1}</div>
  1236→                        <div class="guide-step-content">
  1237→                            <h5>第${index + 1}步：${actionIcons[step.action]} ${actionLabels[step.action]}</h5>
  1238→                            <p>${advice}</p>
  1239→                        </div>
  1240→                    </div>
  1241→                `;
  1242→            });
  1243→
  1244→            document.getElementById('guideSteps').innerHTML = html;
  1245→
  1246→            // 统计
  1247→            const handSteps = state.steps.filter(s => s.action.includes('hand')).length;
