   959→        function generateStepDescription(action, stepIndex) {
   960→            const prevStep = stepIndex > 0 ? state.steps[stepIndex - 1] : null;
   961→
   962→            if (action === 'start') return '准备起步，调整好身体姿势';
   963→            if (action === 'finish') return '完成攀登！双手抓稳顶点';
   964→
   965→            let desc = actionLabels[action];
   966→            if (prevStep && prevStep.action !== 'start') {
   967→                const dx = state.steps[stepIndex]?.x - prevStep.x || 0;
   968→                const dy = state.steps[stepIndex]?.y - prevStep.y || 0;
   969→
   970→                if (Math.abs(dy) > 50 || Math.abs(dx) > 50) {
   971→                    if (dy < -50) desc += '，向上发力';
   972→                    else if (dy > 50) desc += '，向下移动';
   973→                    if (dx > 50) desc += '，向右侧移';
   974→                    else if (dx < -50) desc += '，向左侧移';
   975→                }
   976→            }
   977→            return desc;
   978→        }
