  1158→        function drawLabeledPoint(ctx, x, y, color, label, radius) {
  1159→            ctx.beginPath();
  1160→            ctx.arc(x, y, radius, 0, Math.PI * 2);
  1161→            ctx.fillStyle = color;
  1162→            ctx.fill();
  1163→            ctx.strokeStyle = '#fff';
  1164→            ctx.lineWidth = 3;
  1165→            ctx.stroke();
  1166→
  1167→            ctx.font = 'bold 13px sans-serif';
  1168→            const textWidth = ctx.measureText(label).width;
  1169→            const labelX = x + radius + 6;
  1170→
  1171→            ctx.fillStyle = 'rgba(0,0,0,0.85)';
  1172→            ctx.beginPath();
  1173→            ctx.roundRect(labelX - 4, y - 10, textWidth + 8, 20, 4);
  1174→            ctx.fill();
  1175→
  1176→            ctx.fillStyle = '#fff';
  1177→            ctx.textAlign = 'left';
  1178→            ctx.textBaseline = 'middle';
  1179→            ctx.fillText(label, labelX, y);
  1180→        }
