   884→    <script>
   885→        // 状态
   886→        const state = {
   887→            selectedColor: 'green',
   888→            holds: [], // 用户标记的岩点 {x, y}
   889→            route: [], // AI生成的攀爬路线 {x, y, action, description, technique}
   890→            image: null,
   891→            imageLoaded: false,
   892→            zoom: 1,
   893→            originalWidth: 0,
   894→            originalHeight: 0,
   895→            exportData: null,
   896→            phase: 'upload' // 'upload' | 'marking' | 'complete'
   897→        };
   898→
   899→        const colorMap = {
   900→            green: '#22c55e', red: '#ef4444', pink: '#ec4899', blue: '#3b82f6',
   901→            yellow: '#eab308', purple: '#a855f7', orange: '#f97316', white: '#ffffff'
   902→        };
   903→
   904→        const colorNames = {
   905→            green: '绿色', red: '红色', pink: '粉色', blue: '蓝色',
   906→            yellow: '黄色', purple: '紫色', orange: '橙色', white: '白色'
   907→        };
   908→
   909→        // DOM
   910→        const uploadArea = document.getElementById('uploadArea');
   911→        const fileInput = document.getElementById('fileInput');
   912→        const canvasWrapper = document.getElementById('canvasWrapper');
   913→        const canvas = document.getElementById('mainCanvas');
   914→        const ctx = canvas.getContext('2d');
   915→
   916→        function init() {
   917→            // 上传
   918→            uploadArea.addEventListener('click', () => fileInput.click());
   919→            uploadArea.addEventListener('dragover', e => { e.preventDefault(); uploadArea.style.borderColor = '#00d9ff'; });
   920→            uploadArea.addEventListener('dragleave', () => { uploadArea.style.borderColor = 'rgba(0,217,255,0.5)'; });
   921→            uploadArea.addEventListener('drop', e => {
   922→                e.preventDefault();
   923→                if (e.dataTransfer.files[0]?.type.startsWith('image/')) loadImage(e.dataTransfer.files[0]);
   924→            });
   925→            fileInput.addEventListener('change', e => { if (e.target.files[0]) loadImage(e.target.files[0]); });
   926→
   927→            // 颜色
   928→            document.querySelectorAll('.color-btn').forEach(btn => {
   929→                btn.addEventListener('click', () => {
   930→                    document.querySelectorAll('.color-btn').forEach(b => b.classList.remove('selected'));
   931→                    btn.classList.add('selected');
   932→                    state.selectedColor = btn.dataset.color;
   933→                    redrawCanvas();
   934→                });
   935→            });
   936→
   937→            // Canvas点击
   938→            canvas.addEventListener('click', handleCanvasClick);
   939→
   940→            // 缩放
   941→            document.getElementById('zoomIn').addEventListener('click', () => setZoom(state.zoom + 0.25));
   942→            document.getElementById('zoomOut').addEventListener('click', () => setZoom(state.zoom - 0.25));
   943→            document.getElementById('fitBtn').addEventListener('click', fitToWindow);
   944→            document.getElementById('actualBtn').addEventListener('click', () => setZoom(1));
   945→            canvasWrapper.addEventListener('wheel', e => {
   946→                if (e.ctrlKey || e.metaKey) {
   947→                    e.preventDefault();
   948→                    setZoom(state.zoom + (e.deltaY > 0 ? -0.1 : 0.1));
   949→                }
   950→            });
   951→
   952→            // 按钮
   953→            document.getElementById('analyzeBtn').addEventListener('click', analyzeRoute);
   954→            document.getElementById('downloadBtn').addEventListener('click', downloadImage);
   955→            document.getElementById('downloadBtnModal').addEventListener('click', downloadImage);
   956→            document.getElementById('viewGuideBtn').addEventListener('click', () => document.getElementById('routeModal').classList.add('active'));
   957→            document.getElementById('clearHoldsBtn').addEventListener('click', clearHolds);
   958→            document.getElementById('closeRouteModal').addEventListener('click', () => document.getElementById('routeModal').classList.remove('active'));
   959→            document.getElementById('closeRouteModalBtn').addEventListener('click', () => document.getElementById('routeModal').classList.remove('active'));
   960→        }
   961→
   962→        function loadImage(file) {
   963→            const reader = new FileReader();
   964→            reader.onload = e => {
   965→                const img = new Image();
   966→                img.onload = () => {
   967→                    state.image = img;
   968→                    state.imageLoaded = true;
   969→                    state.originalWidth = img.width;
   970→                    state.originalHeight = img.height;
   971→                    uploadArea.classList.add('hidden');
   972→                    canvas.classList.remove('hidden');
   973→
   974→                    // 更新状态
   975→                    state.phase = 'marking';
   976→                    updateWorkflowUI();
   977→
   978→                    fitToWindow();
   979→                };
   980→                img.src = e.target.result;
   981→            };
   982→            reader.readAsDataURL(file);
   983→        }
   984→
   985→        function updateWorkflowUI() {
   986→            const step1 = document.getElementById('step1');
   987→            const step2 = document.getElementById('step2');
   988→            const step3 = document.getElementById('step3');
   989→
   990→            step1.classList.remove('active', 'completed');
   991→            step2.classList.remove('active', 'completed');
   992→            step3.classList.remove('active', 'completed');
   993→
   994→            if (state.phase === 'upload') {
   995→                step1.classList.add('active');
   996→            } else if (state.phase === 'marking') {
   997→                step1.classList.add('completed');
   998→                step2.classList.add('active');
   999→                document.getElementById('markingPanel').style.display = 'block';
  1000→                document.getElementById('stepsPanel').style.display = 'block';
  1001→                document.getElementById('clearHoldsBtn').style.display = 'block';
  1002→            } else if (state.phase === 'complete') {
  1003→                step1.classList.add('completed');
  1004→                step2.classList.add('completed');
  1005→                step3.classList.add('completed');
  1006→            }
  1007→
  1008→            updateHoldCount();
  1009→        }
  1010→
  1011→        function setZoom(newZoom) {
  1012→            state.zoom = Math.max(0.25, Math.min(4, newZoom));
  1013→            document.getElementById('zoomLevel').textContent = Math.round(state.zoom * 100) + '%';
  1014→            canvas.width = state.originalWidth * state.zoom;
  1015→            canvas.height = state.originalHeight * state.zoom;
  1016→            redrawCanvas();
  1017→        }
  1018→
  1019→        function fitToWindow() {
  1020→            if (!state.image) return;
  1021→            const rect = canvasWrapper.getBoundingClientRect();
  1022→            const scale = Math.min((rect.width - 80) / state.originalWidth, (rect.height - 80) / state.originalHeight, 1);
  1023→            setZoom(scale);
  1024→        }
  1025→
  1026→        function handleCanvasClick(e) {
  1027→            if (!state.imageLoaded || state.phase !== 'marking') return;
  1028→
  1029→            const rect = canvas.getBoundingClientRect();
  1030→            const x = (e.clientX - rect.left) / state.zoom;
  1031→            const y = (e.clientY - rect.top) / state.zoom;
  1032→
  1033→            // 检查是否点击了已有的岩点（删除）
  1034→            const existingIndex = state.holds.findIndex(h => {
  1035→                const dist = Math.sqrt((h.x - x) ** 2 + (h.y - y) ** 2);
  1036→                return dist < 25;
  1037→            });
  1038→
  1039→            if (existingIndex >= 0) {
  1040→                state.holds.splice(existingIndex, 1);
  1041→            } else {
  1042→                state.holds.push({ x, y });
  1043→            }
  1044→
  1045→            updateHoldCount();
  1046→            redrawCanvas();
  1047→        }
  1048→
  1049→        function updateHoldCount() {
  1050→            document.getElementById('holdCount').textContent = state.holds.length;
  1051→
  1052→            const analyzeBtn = document.getElementById('analyzeBtn');
  1053→            if (state.holds.length >= 3 && state.phase === 'marking') {
  1054→                analyzeBtn.style.display = 'block';
  1055→                analyzeBtn.disabled = false;
  1056→            } else {
  1057→                analyzeBtn.style.display = state.phase === 'marking' ? 'block' : 'none';
  1058→                analyzeBtn.disabled = true;
  1059→            }
  1060→        }
  1061→
  1062→        function redrawCanvas() {
  1063→            if (!state.image) return;
  1064→            ctx.clearRect(0, 0, canvas.width, canvas.height);
  1065→            ctx.drawImage(state.image, 0, 0, canvas.width, canvas.height);
  1066→
  1067→            const z = state.zoom;
  1068→            const mainColor = colorMap[state.selectedColor];
  1069→
  1070→            if (state.phase === 'marking') {
  1071→                // 画岩点标记（简单圆点）
  1072→                state.holds.forEach((hold, index) => {
  1073→                    ctx.beginPath();
  1074→                    ctx.arc(hold.x * z, hold.y * z, 18 * z, 0, Math.PI * 2);
  1075→                    ctx.fillStyle = mainColor;
  1076→                    ctx.globalAlpha = 0.8;
  1077→                    ctx.fill();
  1078→                    ctx.globalAlpha = 1;
  1079→                    ctx.strokeStyle = '#fff';
  1080→                    ctx.lineWidth = 3 * z;
  1081→                    ctx.stroke();
  1082→
  1083→                    // 小数字
  1084→                    ctx.fillStyle = '#fff';
  1085→                    ctx.font = `bold ${12 * z}px sans-serif`;
  1086→                    ctx.textAlign = 'center';
  1087→                    ctx.textBaseline = 'middle';
  1088→                    ctx.fillText(String(index + 1), hold.x * z, hold.y * z);
  1089→                });
  1090→            } else if (state.phase === 'complete' && state.route.length > 0) {
  1091→                // 画连接箭头
  1092→                for (let i = 0; i < state.route.length - 1; i++) {
  1093→                    drawArrowOnCanvas(
  1094→                        state.route[i].x * z, state.route[i].y * z,
  1095→                        state.route[i+1].x * z, state.route[i+1].y * z,
  1096→                        mainColor
  1097→                    );
  1098→                }
  1099→
  1100→                // 画路线点
  1101→                state.route.forEach((step, index) => {
  1102→                    let color = mainColor;
  1103→                    let label = String(index + 1);
  1104→
  1105→                    if (index === 0) { color = '#22c55e'; label = '起'; }
  1106→                    else if (index === state.route.length - 1) { color = '#ef4444'; label = '终'; }
  1107→                    else if (step.action.includes('脚')) { color = '#64748b'; }
  1108→
  1109→                    drawLabeledPointOnCanvas(step.x * z, step.y * z, color, label, step.action, 20 * z);
  1110→                });
  1111→            }
  1112→        }
  1113→
  1114→        function drawArrowOnCanvas(x1, y1, x2, y2, color) {
  1115→            const dx = x2 - x1, dy = y2 - y1;
  1116→            const angle = Math.atan2(dy, dx);
  1117→            const dist = Math.sqrt(dx*dx + dy*dy);
  1118→            const shorten = 25 * state.zoom;
  1119→
  1120→            if (dist < shorten * 2) return;
  1121→
  1122→            const ratio = (dist - shorten) / dist;
  1123→            const startX = x1 + dx * (shorten/dist), startY = y1 + dy * (shorten/dist);
  1124→            const endX = x1 + dx * ratio, endY = y1 + dy * ratio;
  1125→
  1126→            ctx.beginPath();
  1127→            ctx.moveTo(startX, startY);
  1128→            ctx.lineTo(endX, endY);
  1129→            ctx.strokeStyle = color;
  1130→            ctx.lineWidth = 3 * state.zoom;
  1131→            ctx.stroke();
  1132→
  1133→            // 箭头
  1134→            const arrowSize = 10 * state.zoom;
  1135→            ctx.beginPath();
  1136→            ctx.moveTo(endX, endY);
  1137→            ctx.lineTo(endX - arrowSize*Math.cos(angle-Math.PI/6), endY - arrowSize*Math.sin(angle-Math.PI/6));
  1138→            ctx.moveTo(endX, endY);
  1139→            ctx.lineTo(endX - arrowSize*Math.cos(angle+Math.PI/6), endY - arrowSize*Math.sin(angle+Math.PI/6));
  1140→            ctx.stroke();
  1141→        }
  1142→
  1143→        function drawLabeledPointOnCanvas(x, y, color, label, action, radius) {
  1144→            // 外圈
  1145→            ctx.beginPath();
  1146→            ctx.arc(x, y, radius + 3 * state.zoom, 0, Math.PI * 2);
  1147→            ctx.strokeStyle = '#fff';
  1148→            ctx.lineWidth = 3 * state.zoom;
  1149→            ctx.stroke();
  1150→
  1151→            // 内圆
  1152→            ctx.beginPath();
  1153→            ctx.arc(x, y, radius, 0, Math.PI * 2);
  1154→            ctx.fillStyle = color;
  1155→            ctx.fill();
  1156→
  1157→            // 数字
  1158→            ctx.fillStyle = '#fff';
  1159→            ctx.font = `bold ${radius * 0.8}px sans-serif`;
  1160→            ctx.textAlign = 'center';
  1161→            ctx.textBaseline = 'middle';
  1162→            ctx.fillText(label, x, y);
  1163→
  1164→            // 动作标签
