  1209→        // AI核心算法：计算最佳攀爬路线
  1210→        function calculateClimbingRoute(holds) {
  1211→            if (holds.length === 0) return [];
  1212→
  1213→            // 1. 按Y坐标排序（从下到上）
  1214→            const sortedByY = [...holds].sort((a, b) => b.y - a.y);
  1215→
  1216→            // 2. 找到起点（最下面的2个点作为起步手点）
  1217→            const startHolds = sortedByY.slice(0, Math.min(2, holds.length));
  1218→
  1219→            // 3. 找到终点（最上面的点）
  1220→            const endHold = sortedByY[sortedByY.length - 1];
  1221→
  1222→            // 4. 贪心算法：从下往上，交替选择左右手/脚
  1223→            const route = [];
  1224→            const used = new Set();
  1225→
  1226→            // 起点
  1227→            if (startHolds.length >= 2) {
  1228→                const leftStart = startHolds[0].x < startHolds[1].x ? startHolds[0] : startHolds[1];
  1229→                const rightStart = startHolds[0].x < startHolds[1].x ? startHolds[1] : startHolds[0];
  1230→
  1231→                route.push({ ...leftStart, action: '左手起步', isStart: true });
  1232→                route.push({ ...rightStart, action: '右手起步', isStart: true });
  1233→                used.add(JSON.stringify(leftStart));
  1234→                used.add(JSON.stringify(rightStart));
  1235→            } else {
  1236→                route.push({ ...startHolds[0], action: '双手起步', isStart: true });
  1237→                used.add(JSON.stringify(startHolds[0]));
  1238→            }
  1239→
  1240→            // 中间路线：贪心选择最近的未使用岩点
  1241→            let lastPos = {
  1242→                x: (startHolds[0].x + (startHolds[1]?.x || startHolds[0].x)) / 2,
  1243→                y: startHolds[0].y
  1244→            };
  1245→
  1246→            // 交替使用手脚
  1247→            const actionSequence = ['左脚', '右手', '右脚', '左手'];
  1248→            let actionIndex = 0;
  1249→
  1250→            // 按高度分层处理
  1251→            const remainingHolds = holds.filter(h => !used.has(JSON.stringify(h)));
  1252→            const layers = [];
  1253→
  1254→            // 把剩余岩点分成若干层
  1255→            const layerHeight = (startHolds[0].y - endHold.y) / Math.max(4, Math.ceil(remainingHolds.length / 2));
  1256→
  1257→            remainingHolds.forEach(hold => {
  1258→                const layerIndex = Math.floor((startHolds[0].y - hold.y) / layerHeight);
  1259→                if (!layers[layerIndex]) layers[layerIndex] = [];
  1260→                layers[layerIndex].push(hold);
  1261→            });
  1262→
  1263→            // 逐层处理
  1264→            layers.forEach((layer, layerIdx) => {
  1265→                if (!layer) return;
  1266→
  1267→                // 按X排序
  1268→                layer.sort((a, b) => a.x - b.x);
  1269→
  1270→                layer.forEach(hold => {
  1271→                    if (used.has(JSON.stringify(hold))) return;
  1272→
  1273→                    const action = actionSequence[actionIndex % actionSequence.length];
  1274→
  1275→                    // 根据位置调整动作
  1276→                    let finalAction = action;
  1277→                    const centerX = state.originalWidth / 2;
  1278→
  1279→                    if (action.includes('手')) {
  1280→                        if (hold.x < centerX - 50) finalAction = '左手';
  1281→                        else if (hold.x > centerX + 50) finalAction = '右手';
  1282→                    } else {
  1283→                        if (hold.x < centerX - 30) finalAction = '左脚';
  1284→                        else if (hold.x > centerX + 30) finalAction = '右脚';
  1285→                    }
  1286→
  1287→                    route.push({ ...hold, action: finalAction });
  1288→                    used.add(JSON.stringify(hold));
  1289→                    actionIndex++;
  1290→                });
  1291→            });
  1292→
  1293→            // 终点
  1294→            if (!used.has(JSON.stringify(endHold))) {
  1295→                route.push({ ...endHold, action: '完成攀登', isEnd: true });
  1296→            } else {
  1297→                route[route.length - 1].isEnd = true;
  1298→                route[route.length - 1].action = '完成攀登';
  1299→            }
  1300→
  1301→            // 为每个步骤生成详细说明
  1302→            route.forEach((step, index) => {
  1303→                step.description = generateStepDescription(step, index, route);
  1304→                step.technique = generateTechnique(step, index, route);
  1305→            });
  1306→
  1307→            return route;
  1308→        }
  1309→
  1310→        function generateStepDescription(step, index, route) {
  1311→            if (step.isStart) {
  1312→                return '双手找到起点岩点，身体贴近岩壁，重心放低，准备开始攀爬。';
  1313→            }
  1314→            if (step.isEnd) {
  1315→                return '最后冲刺！双手抓稳顶点，保持3秒确认完成。恭喜你完成攀登！';
  1316→            }
  1317→
  1318→            const prevStep = route[index - 1];
  1319→            if (!prevStep) return step.action;
  1320→
  1321→            const dx = step.x - prevStep.x;
  1322→            const dy = step.y - prevStep.y;
  1323→            const distance = Math.sqrt(dx * dx + dy * dy);
  1324→
  1325→            let desc = '';
  1326→
  1327→            if (step.action.includes('手')) {
  1328→                desc = step.action + '向';
  1329→                if (dy < -50) desc += '上方';
  1330→                if (dx > 30) desc += '右侧';
  1331→                else if (dx < -30) desc += '左侧';
  1332→                desc += '移动抓握。';
  1333→
  1334→                if (distance > 100) {
  1335→                    desc += '跨度较大，需要先移动重心。';
  1336→                }
  1337→            } else {
  1338→                desc = step.action + '踩踏';
  1339→                if (dy < -30) desc += '上方';
  1340→                if (dx > 20) desc += '右侧';
  1341→                else if (dx < -20) desc += '左侧';
  1342→                desc += '岩点。';
  1343→
  1344→                desc += '用脚尖内侧精准踩点，踩稳后再转移重心。';
  1345→            }
  1346→
  1347→            return desc;
  1348→        }
  1349→
  1350→        function generateTechnique(step, index, route) {
  1351→            if (step.isStart) {
  1352→                return '三点固定原则：移动一个肢体时，保持其他三个肢体稳定。';
  1353→            }
  1354→            if (step.isEnd) {
  1355→                return '最后一步可以适当动态发力，但要确保抓稳。';
  1356→            }
  1357→
  1358→            const tips = [];
  1359→
  1360→            if (step.action.includes('手')) {
  1361→                tips.push('根据岩点形状选择抓握方式：指洞用指尖抠、平台用掌心包、侧拉用指节勾');
  1362→            } else {
  1363→                tips.push('脚踩稳后再移动重心，避免打滑');
  1364→            }
  1365→
  1366→            const prevStep = route[index - 1];
  1367→            if (prevStep) {
  1368→                const dy = step.y - prevStep.y;
  1369→                if (dy < -80) {
  1370→                    tips.push('向上移动时多用腿部发力，手臂主要保持平衡');
  1371→                }
  1372→            }
  1373→
  1374→            return tips.join('。') + '。';
  1375→        }
