  1435→        function drawArrowExport(ctx, x1, y1, x2, y2, color) {
  1436→            const dx = x2 - x1, dy = y2 - y1;
  1437→            const angle = Math.atan2(dy, dx);
  1438→            const dist = Math.sqrt(dx*dx + dy*dy);
  1439→            const shorten = 28;
  1440→
  1441→            if (dist < shorten * 2) return;
  1442→
  1443→            const ratio = (dist - shorten) / dist;
  1444→            const startX = x1 + dx * (shorten/dist), startY = y1 + dy * (shorten/dist);
  1445→            const endX = x1 + dx * ratio, endY = y1 + dy * ratio;
  1446→
  1447→            ctx.beginPath();
  1448→            ctx.moveTo(startX, startY);
  1449→            ctx.lineTo(endX, endY);
  1450→            ctx.strokeStyle = color;
  1451→            ctx.lineWidth = 4;
  1452→            ctx.stroke();
  1453→
  1454→            ctx.beginPath();
  1455→            ctx.moveTo(endX, endY);
  1456→            ctx.lineTo(endX - 12*Math.cos(angle-Math.PI/6), endY - 12*Math.sin(angle-Math.PI/6));
  1457→            ctx.moveTo(endX, endY);
  1458→            ctx.lineTo(endX - 12*Math.cos(angle+Math.PI/6), endY - 12*Math.sin(angle+Math.PI/6));
  1459→            ctx.stroke();
  1460→        }
  1461→
  1462→        function drawLabeledPointExport(ctx, x, y, color, label, radius) {
  1463→            ctx.beginPath();
  1464→            ctx.arc(x, y, radius, 0, Math.PI * 2);
  1465→            ctx.fillStyle = color;
  1466→            ctx.fill();
  1467→            ctx.strokeStyle = '#fff';
  1468→            ctx.lineWidth = 3;
  1469→            ctx.stroke();
  1470→
  1471→            ctx.font = 'bold 13px sans-serif';
  1472→            const textWidth = ctx.measureText(label).width;
  1473→            const labelX = x + radius + 6;
  1474→
  1475→            ctx.fillStyle = 'rgba(0,0,0,0.85)';
  1476→            ctx.beginPath();
  1477→            ctx.roundRect(labelX - 4, y - 10, textWidth + 8, 20, 4);
  1478→            ctx.fill();
  1479→
  1480→            ctx.fillStyle = '#fff';
  1481→            ctx.textAlign = 'left';
  1482→            ctx.textBaseline = 'middle';
  1483→            ctx.fillText(label, labelX, y);
  1484→        }
